const stateEncoder = require('./stateEncoder');
const actionEncoder = require('./actionEncoder');

class RLEnvironment {
    constructor() {
        this.mode = "OFFLINE_HISTORICAL";
        this.episodeMode = "single-transition-historical";
        this.version = "environment-v1";
        
        this.currentTransition = null;
        this.done = true;
    }

    /**
     * Initializes the environment with a historical transition.
     * @param {Object} historicalTransition - A transition generated by datasetBuilder.
     */
    reset(historicalTransition) {
        if (!historicalTransition || !historicalTransition.state || !historicalTransition.actionMask) {
            throw new Error("Invalid historical transition provided to reset().");
        }

        this.currentTransition = historicalTransition;
        this.done = false;

        return {
            state: this.currentTransition.state,
            actionMask: this.currentTransition.actionMask,
            done: this.done,
            metadata: this.getMetadata()
        };
    }

    /**
     * Attempts to execute an action. In OFFLINE_HISTORICAL mode, we only permit the historically taken action, 
     * or at least we evaluate if the action is valid. But we CANNOT fabricate rewards for actions that weren't historically taken.
     * @param {number} actionId - The ID of the action to execute.
     */
    step(actionId) {
        if (this.done) {
            throw new Error("Environment is done. Please call reset().");
        }

        if (!this.currentTransition) {
            throw new Error("Environment not initialized.");
        }

        const validActions = this.getValidActions();
        
        // 1. Validate if action is possible
        if (!validActions.includes(actionId)) {
            return {
                state: this.currentTransition.state,
                action: actionId,
                reward: null,
                nextState: null,
                done: true,
                info: { error: "ACTION_INVALID", reason: "Action incompatible with category or resource constraints." }
            };
        }

        // 2. Validate if action matches historical offline data
        if (actionId !== this.currentTransition.action) {
            return {
                state: this.currentTransition.state,
                action: actionId,
                reward: null,
                nextState: null,
                done: true,
                info: { error: "OFFLINE_MISMATCH", reason: "Cannot fabricate reward for non-historical action in OFFLINE_HISTORICAL mode." }
            };
        }

        // 3. Historical match: Provide real outcome
        this.done = true; // single-transition semantics
        return {
            state: this.currentTransition.state,
            action: actionId,
            reward: this.currentTransition.reward,
            nextState: this.currentTransition.nextState,
            done: this.done,
            info: { success: true }
        };
    }

    getState() {
        if (!this.currentTransition) return null;
        return this.currentTransition.state;
    }

    getValidActions() {
        if (!this.currentTransition) return [];
        const valid = [];
        const mask = this.currentTransition.actionMask;
        for (let i = 0; i < mask.length; i++) {
            if (mask[i] === 1) valid.push(i);
        }
        return valid;
    }

    isDone() {
        return this.done;
    }

    getMetadata() {
        return {
            environmentVersion: this.version,
            mode: this.mode,
            episodeMode: this.episodeMode,
            stateVersion: stateEncoder.VERSION,
            actionVersion: actionEncoder.VERSION,
            resourceAvailabilityStatus: this.currentTransition ? this.currentTransition.resourceAvailabilityStatus : null
        };
    }
}

module.exports = RLEnvironment;
